import { useEffect, useMemo, useState } from "react";
import { Link, useParams } from "wouter";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Skeleton } from "@/components/ui/skeleton";
import { SEOHead } from "@/components/SEOHead";
import type { CamDoc } from "@/lib/camTypes";

/**
 * Serves /cams and /cams/<manufacturer> from one dataset.
 *
 * Both read /data/cam-pages/index.json, generated by scripts/camData.mjs from
 * the same camDatabase.ts the Cam Selector uses — so the two cannot drift, and
 * adding a grind to the selector publishes a page for it.
 */
export default function CamsIndexPage() {
  const { mfr } = useParams<{ mfr?: string }>();
  const [doc, setDoc] = useState<CamDoc | null>(null);

  useEffect(() => {
    fetch("/data/cam-pages/index.json")
      .then((r) => r.json())
      .then(setDoc)
      .catch(() => setDoc({ cams: [], manufacturers: [] }));
  }, []);

  const current = useMemo(
    () => (mfr && doc ? doc.manufacturers.find((m) => m.url === `/cams/${mfr}`) ?? null : null),
    [mfr, doc]
  );
  const cams = useMemo(
    () => (doc ? (mfr ? doc.cams.filter((c) => c.mfrUrl === `/cams/${mfr}`) : doc.cams) : []),
    [doc, mfr]
  );

  if (!doc) {
    return (
      <div className="container mx-auto max-w-5xl py-10 px-4">
        <Skeleton className="h-10 w-72 mb-6" />
        <Skeleton className="h-64 rounded-lg" />
      </div>
    );
  }

  if (mfr && !current) {
    return (
      <div className="container mx-auto max-w-5xl py-10 px-4 text-center">
        <h1 className="text-2xl font-bold mb-4">Cam manufacturer not found</h1>
        <Link href="/cams" className="text-[#E85D04] hover:underline">Browse all camshafts</Link>
      </div>
    );
  }

  const title = current ? `${current.name} Camshaft Specs` : "Camshaft Specs Database";
  const description = current
    ? `Duration at 0.050", lift, LSA and RPM range for ${current.count} ${current.name} camshaft grinds, with part numbers.`
    : `Duration at 0.050", lift, LSA and RPM range for ${doc.cams.length} camshaft grinds across ${doc.manufacturers.length} manufacturers.`;

  return (
    <div className="container mx-auto max-w-5xl py-10 px-4">
      <SEOHead title={title} description={description} canonical={current ? current.url : "/cams"} />

      {current && (
        <nav aria-label="Breadcrumb" className="text-sm text-muted-foreground mb-6">
          <Link href="/cams" className="hover:text-primary">Camshafts</Link>
        </nav>
      )}

      <h1 className="text-4xl font-bold mb-1">{title}</h1>
      <p className="text-muted-foreground mb-8">
        {cams.length} grind{cams.length === 1 ? "" : "s"}
        {!current && ` · ${doc.manufacturers.length} manufacturers`}
      </p>

      {!current && (
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3 mb-10">
          {doc.manufacturers.map((m) => (
            <Link key={m.url} href={m.url}>
              <Card className="h-full hover:border-[#E85D04] transition-colors">
                <CardContent className="pt-5">
                  <p className="font-semibold text-sm">{m.name}</p>
                  <p className="text-xs text-muted-foreground">{m.count} grinds</p>
                </CardContent>
              </Card>
            </Link>
          ))}
        </div>
      )}

      <Card>
        <CardHeader className="pb-3"><CardTitle className="text-base">Specifications</CardTitle></CardHeader>
        <CardContent>
          <div className="overflow-x-auto">
            <table className="w-full text-sm min-w-[700px]">
              <thead>
                <tr className="border-b">
                  <th className="text-left py-2 pr-4 font-medium">Cam</th>
                  <th className="text-left py-2 pr-4 font-medium">Part</th>
                  <th className="text-left py-2 pr-4 font-medium">Platform</th>
                  <th className="text-left py-2 pr-4 font-medium">Dur @.050"</th>
                  <th className="text-left py-2 pr-4 font-medium">Lift</th>
                  <th className="text-left py-2 font-medium">LSA</th>
                </tr>
              </thead>
              <tbody>
                {cams.map((c) => (
                  <tr key={c.url} className="border-b last:border-0">
                    <td className="py-2 pr-4">
                      <Link href={c.url} className="text-[#E85D04] hover:underline font-medium">
                        {!current ? `${c.mfr} ` : ""}{c.family}
                      </Link>
                    </td>
                    <td className="py-2 pr-4 tabular-nums whitespace-nowrap">{c.part}</td>
                    <td className="py-2 pr-4 whitespace-nowrap">{c.platformLabel}</td>
                    <td className="py-2 pr-4 tabular-nums whitespace-nowrap">
                      {c.int050}{c.exh050 != null ? `/${c.exh050}` : ""}
                    </td>
                    <td className="py-2 pr-4 tabular-nums whitespace-nowrap">{c.liftInt}"/{c.liftExh}"</td>
                    <td className="py-2 tabular-nums">{c.lsa}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </CardContent>
      </Card>

      <p className="text-xs text-muted-foreground mt-8">
        Specs and part numbers change. Always confirm current data with the manufacturer before ordering.
      </p>
    </div>
  );
}
